APP_CATALOG.loadExternalCatalog = async function() {
  try {
    const res = await fetch('data/catalog.json');
    if (res.ok) {
      const data = await res.json();
      if (data.employees) this.employees = data.employees;
      if (data.operations) this.operations = data.operations;
      if (data.units) this.units = data.units;
      console.log('Каталог успішно оновлено з data/catalog.json');
    }
  } catch (e) {
    console.warn('Використовується вбудований каталог (fetch catalog.json недоступний):', e);
  }
};
